<script>
$(document).ready(function(){
	$("img[src='star.png']").attr('title','Clique para dar nota');
	$("img[src='star_blank.png']").attr('title','Clique para dar nota');
	$( document ).tooltip({
      track: true
    });
});

function prov1(){
	$('#tamcerto').css("height", $('#busca').height() - $('.divbusca').height()*2);
	$('.superDiv').hide();
}
prov1();

function buscainterna(){
	palavrachave = $("#palavrachave").val();
	buscarpor("",palavrachave,0);	
}
fase=0;
function abreBuscaAvancada(){
	$('.superDiv').slideToggle(300, function (){
		if(fase==0){
			$('#tamcerto').css("height", $('#busca').height() - $('.divbusca').height()*2 - $('.superDiv').height());
			fase=1;
		}else{
			$('#tamcerto').css("height", $('#busca').height() - $('.divbusca').height()*2);
			fase=0;
		}
	});
	
}

function fazabuscafinalmente(){
	if($('#chave').val() == ""){
		chave=0;
	}else{
		chave=$('#chave').val();
	}
	
	if($('#super').val() == ""){
		tema=0;
	}else{
		tema=$('#super').val();
	}
	n=-1;
	tagvet = new Array();
    $('#tagbusca input:checked').each(function(){
		n++;
    	tagvet[n]=$(this).parent().text();
    });
	if(n==-1){
		tagvet[0]="";	
	}
	
	buscarpor(tema,chave,tagvet);
}

function nota(valornota,id){
	dataenvio='nota='+valornota+"&id="+id;
	$.ajax(
		{			
			type: "POST",
			url: "nota.php",
			data: dataenvio,
			beforeSend: function() {
				//antes de enviar (por um aviso de loading etc...)
			},success: function(txt) {
				//sucesso:
				alert(txt);
			},error: function(txt) {
				// em caso de erro você pode dar um alert('erro');
				alert("Erro AJAX no voto. Informe o Rosh Internet!!!");
			}
		}
		);
}
</script>
